 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The frame is a fixed two-color border; the patterned field begins at (3, 3).
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0 and (r < 3 or c < 3):
                out[r][c] = 1 if r < 2 or c < 2 else 4

    # Find the horizontal repeat length of the visible pattern. Each row may
    # have its own phase, while the stream's pattern period is shared.
    rows = range(3, h)
    best_period, best_score = 1, -1.0
    max_period = min(12, max(1, w - 3))
    for p in range(1, max_period + 1):
        good = total = 0
        for r in rows:
            vals = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
            if len(vals) < p + 1:
                continue
            buckets = {}
            for c, v in vals:
                buckets.setdefault((c - 3) % p, []).append(v)
            modes = {k: Counter(vs).most_common(1)[0][0] for k, vs in buckets.items()}
            good += sum(v == modes[(c - 3) % p] for c, v in vals)
            total += len(vals)
        score = good / total if total else 0
        if score > best_score + 1e-12:
            best_period, best_score = p, score

    for r in rows:
        vals = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        buckets = {}
        for c, v in vals:
            buckets.setdefault((c - 3) % best_period, []).append(v)
        modes = {k: Counter(vs).most_common(1)[0][0] for k, vs in buckets.items()}
        for c in range(3, w):
            if out[r][c] == 0:
                out[r][c] = modes[(c - 3) % best_period]
    return out
